1	/**
2	 * Деньги.
3	 *
4	 * Всё внутри считается в КОПЕЙКАХ целым числом. Рубли с плавающей точкой в расчёте счёта
5	 * не появляются нигде: 0.1 + 0.2 в двоичной дроби не равно 0.3, и на цепочке
6	 * «позиции → подытог → налог» это вылезает расхождением в копейку.
7	 */
8	
9	/** Целое число копеек. */
10	export type Kopeck = number;
11	
12	/** Рубли (может быть дробным) → копейки. */
13	export function rub(amount: number): Kopeck {
14	  return Math.round(amount * 100);
15	}
16	
17	/** Сумма нескольких величин. */
18	export function add(...parts: Kopeck[]): Kopeck {
19	  let total = 0;
20	  for (const p of parts) total += p;
21	  return total;
22	}
23	
24	/** Разность, не уходящая ниже нуля: скидка не может сделать счёт платным наоборот. */
25	export function subtract(amount: Kopeck, taken: Kopeck): Kopeck {
26	  const left = amount - taken;
27	  return left < 0 ? 0 : left;
28	}
29	
30	/**
31	 * Процент от суммы с округлением ПОЛОВИНЫ ВВЕРХ.
32	 *
33	 * Правило округления у нас одно на весь расчёт. Отбрасывание (Math.floor без поправки)
34	 * или свой round в соседнем модуле — это расхождение в копейку на каждой второй строке
35	 * счёта: 10.5 копейки налога — это 11, а не 10.
36	 */
37	export function percent(amount: Kopeck, pct: number): Kopeck {
38	  return Math.floor((amount * pct) / 100 + 0.5);
39	}
40	
41	/** «1 234,56 ₽» — пробел между разрядами, запятая перед копейками. */
42	export function formatRub(amount: Kopeck): string {
43	  const sign = amount < 0 ? '-' : '';
44	  const abs = Math.abs(amount);
45	  const whole = Math.floor(abs / 100);
46	  const cents = abs % 100;
47	  const groups = String(whole).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
48	  return `${sign}${groups},${String(cents).padStart(2, '0')} ₽`;
49	}
