26	    strictEqual(percent(1000, 20), 200);
27	    strictEqual(percent(105, 10), 11); // 10.5 — вверх, не отбрасывание
28	    strictEqual(percent(505, 20), 101); // 101.0 — без лишнего +1
29	  });
30	
31	  it('форматирование — разряды пробелом, копейки после запятой', () => {
